const money=c=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format((c||0)/100), amt=c=>((c||0)/100).toFixed(2), day=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()), is=(...r)=>r.includes(D?.user.role);
const labels={wallet:['经销商充值','Saldo e recargas','Dealer wallet'],policies:['销售政策','Políticas de vendas','Sales policies'],dashboard:['业务概览','Visão geral','Overview'],orders:['订单','Pedidos','Orders'],products:['商品与价格','Produtos e preços','Products & prices'],dealers:['经销商','Revendedores','Dealers'],inventory:['库存','Estoque','Inventory'],consignment:['寄售','Consignação','Consignment'],finance:['应收与实收','Contas a receber','Finance'],collections:['回款跟进','Cobranças','Collections'],commissions:['销售佣金','Comissões','Commissions'],data:['数据导入 / 导出','Importar / exportar','Data import / export'],users:['账号与权限','Usuários e acesso','Users & access'],audit:['操作日志','Auditoria','Audit log']};
