const statuses={WAITING_FINANCE_REVIEW:['待财务审核','Aguardando análise financeira','Awaiting finance review'],VERIFYING:['待核实到账','Aguardando verificação bancária','Awaiting bank verification'],DRAFT:['草稿','Rascunho','Draft'],WAITING_INTERNAL_REVIEW:['待管理员审核','Aguardando administrador','Awaiting admin review'],WAITING_DEALER_CONFIRMATION:['待客户确认','Aguardando cliente','Awaiting dealer'],CONFIRMED:['已生效 · 待发','Confirmado','Confirmed'],PARTIALLY_SHIPPED:['部分出库','Envio parcial','Partially shipped'],SHIPPED:['全部出库','Expedido','Shipped'],CLOSED:['已完成','Concluído','Closed'],REJECTED:['已拒绝','Recusado','Rejected'],CANCELED:['已撤销','Cancelado','Canceled'],EXPIRED:['已过期','Expirado','Expired'],UNPAID:['未付款','Não pago','Unpaid'],PARTIAL:['部分实收','Pagamento parcial','Partial'],PAID:['已核实全收','Pago e verificado','Verified paid'],OVERDUE:['逾期','Vencido','Overdue'],PENDING:['待核实','Pendente','Pending'],VERIFIED:['已核实','Verificado','Verified'],APPROVED:['可结算','Aprovado','Approved'],PENDING_PICKUP:['待提货','Aguardando retirada','Awaiting pickup'],DELIVERED:['已交付','Entregue','Delivered'],RETURNED:['已实际退回','Devolvido','Returned'],PREVIEW:['预览','Prévia','Preview'],COMMITTED:['已导入','Importado','Imported'],REVIEW_REQUIRED:['待人工复核','Revisão manual','Manual review'],SUPERSEDED:['已替换','Substituído','Superseded']};
const st=s=>statuses[s]?L(...statuses[s]):s;
const saleTypeName=s=>s==='CASH'?L('现付','À vista','Cash payment'):s==='CONSIGNMENT'?L('寄售','Consignação','Consignment'):s==='OTHER'?L('其他','Outro','Other'):L('普通批发（历史）','Atacado (legado)','Wholesale (legacy)');
const newOrderTitle=()=>is('dealer')?L('新建采购订单','Novo pedido de compra','New purchase order'):L('新建订单','Novo pedido','New order');
const saleDateTitle=()=>is('dealer')?L('采购日期','Data da compra','Purchase date'):L('销售日期','Data da venda','Sale date');
const localPaymentValue=x=>x?x.slice(0,16):'';
const paymentLabel=x=>x?new Intl.DateTimeFormat(lang==='zh'?'zh-CN':lang==='pt'?'pt-BR':'en-US',{timeZone:'America/Sao_Paulo',dateStyle:'medium',timeStyle:'short'}).format(new Date(x)):'—';
const promotionName=s=>s==='DEMO'?'Demo · 80%':s==='TEN_PLUS_ONE'?L('同款10台赠1台','10 unidades + 1 brinde','Buy 10, get 1 free'):L('标准批发价','Preço padrão','Standard wholesale');
const badge=s=>`<span class="badge ${['PAID','CLOSED','CONFIRMED','VERIFIED','APPROVED','DELIVERED','COMMITTED'].includes(s)?'green':['OVERDUE','REJECTED','CANCELED','EXPIRED','RETURNED'].includes(s)?'red':'amber'}">${E(st(s))}</span>`;
const button=(act,text,args='',cls='')=>`<button type="button" class="${cls}" data-act="${act}" data-args="${E(args)}">${text}</button>`;
const empty=()=>`<div class="empty"><div class="blank-icon">◇</div><strong>${L('还没有记录','Nenhum registro','No records yet')}</strong>${L('新增业务后，这里将显示真实数据。','Os dados reais aparecerão aqui.','Your business records will appear here.')}</div>`;
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className=error?'error':'';el.style.display='block';setTimeout(()=>el.style.display='none',5000)}
async function api(path,body,method='POST',key){const headers={};if(body!==undefined&&!(body instanceof FormData))headers['Content-Type']='application/json';if(D)headers['X-CSRF-Token']=D.csrf;if(path.startsWith('/api/action/')||path.startsWith('/api/orders')||path.startsWith('/api/recharges')||path.startsWith('/api/policies/assistant/'))headers['Idempotency-Key']=key||crypto.randomUUID();const r=await fetch(path,{method:body===undefined?'GET':method,headers,body:body===undefined?undefined:body instanceof FormData?body:JSON.stringify(body)});let j;try{j=await r.json()}catch{throw Error('HTTP '+r.status)}if(!r.ok){if(r.status===401&&D)location.reload();throw Error(j.detail||'HTTP '+r.status)}return j}
async function load(){
sharedSynchronizer.invalidate();const ticket=++snapshotGeneration;snapshotLoading=true;
try{const fresh=await api('/api/data');if(ticket!==snapshotGeneration)return;
const initial=!D;D=fresh;sharedSyncError='';if(initial)restoreSharedView();
if(document.body.dataset.appVersion&&D.app_version&&document.body.dataset.appVersion!==D.app_version&&!sharedSyncContext().editing){reloadSharedVersion();return}
loadDashboardPreferences();loadDashboardRankingPreferences();if(view==='dashboard')await refreshDashboard(false);if(ticket===snapshotGeneration)render();
}finally{if(ticket===snapshotGeneration)snapshotLoading=false}
}
let sharedSyncError='',snapshotGeneration=0,snapshotLoading=false,versionReloading=false;
function navigationKeys(){return ['dashboard','orders','products',...(!is('dealer')?['dealers','inventory']:[]),'consignment',...(is('admin','sales')?['policies']:[]),...(is('admin','finance','sales','dealer')?['wallet','finance']:[]),...(is('admin','finance','sales')?['collections','commissions']:[]),'data',...(is('admin')?['users','audit']:[])]}
function sharedSyncContext(){
const modal=$('#modal'),liveModal=modal?.open&&(modal.dataset.liveOrderId||modal.dataset.liveCreditId);
const active=document.activeElement,typing=active?.matches('input:not([type=checkbox]):not([type=radio]),textarea');
return {userId:D?.user.id,view,version:document.body.dataset.appVersion,hidden:document.hidden,loading:snapshotLoading,
editing:Boolean((modal?.open&&!liveModal)||typing||$('#dashboard-draft-status')?.textContent||$('#workbench-draft-status')?.textContent||$('#workbench-rules')?.open)};
}
function syncStatusText(){if(sharedSyncError)return L('同步失败，当前显示上次数据','Falha na atualização; dados anteriores','Sync failed; showing previous data');if(!D?.server_time)return '';const time=new Intl.DateTimeFormat(lang==='zh'?'zh-CN':lang==='pt'?'pt-BR':'en-US',{timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date(D.server_time));return L('已同步 ','Atualizado ','Synced ')+time}
function updateSyncStatus(){const el=$('#shared-sync-status');if(el){el.textContent=syncStatusText();el.classList.toggle('sync-failed',Boolean(sharedSyncError))}}
function reloadSharedVersion(){
if(versionReloading)return;versionReloading=true;
try{sessionStorage.setItem('hynak_resume_'+D.user.id,JSON.stringify({view,inventorySelection,consignmentSelection,dashboardFilters,search,page,filterStatus}))}catch{}
location.reload();
}
function restoreSharedView(){
try{const key='hynak_resume_'+D.user.id,raw=sessionStorage.getItem(key);sessionStorage.removeItem(key);if(!raw)return;const saved=JSON.parse(raw);if(navigationKeys().includes(saved.view))view=saved.view;
if(saved.inventorySelection)inventorySelection=saved.inventorySelection;if(saved.consignmentSelection)consignmentSelection=saved.consignmentSelection;
if(saved.dashboardFilters)dashboardFilters=saved.dashboardFilters;search=typeof saved.search==='string'?saved.search:'';page=Number(saved.page)||1;filterStatus=typeof saved.filterStatus==='string'?saved.filterStatus:'';
}catch{}
}
async function applySharedSnapshot(fresh){
const modal=$('#modal'),oid=modal?.open&&modal.dataset.liveOrderId,cid=modal?.open&&modal.dataset.liveCreditId,position=modal?.scrollTop||0;
const x=window.scrollX,y=window.scrollY;
D=fresh;sharedSyncError='';catalogRefreshError='';loadDashboardPreferences();loadDashboardRankingPreferences();
if(view==='dashboard')await refreshDashboard(false);
if(sharedSyncContext().editing){updateSyncStatus();return}
render();window.scrollTo(x,y);
if(oid&&modal?.open&&modal.dataset.liveOrderId===oid){if(D.orders.some(o=>o.id===Number(oid))){detail(oid);modal.scrollTop=position}else modal.close()}
else if(cid&&modal?.open&&modal.dataset.liveCreditId===cid){if(D.dealers.some(d=>d.id===Number(cid))){await creditRatingDetail(cid);modal.scrollTop=position}else modal.close()}
}
const sharedSynchronizer=HynakSessionSync.create({context:sharedSyncContext,fetchSnapshot:()=>api('/api/data'),applySnapshot:applySharedSnapshot,
onVersionChange:reloadSharedVersion,onSessionChange:()=>location.reload(),onError:()=>{sharedSyncError='failed';updateSyncStatus()}});
async function refreshSharedData(force=false){return sharedSynchronizer.refresh({force})}
setInterval(()=>refreshSharedData(),30000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshSharedData()});
window.addEventListener('focus',()=>refreshSharedData());

const head=(name,subtitle,actions='')=>`<div class="page-heading"><div><div class="eyebrow">HYNAK / ${E(title(name))}</div><h1>${E(title(name))}</h1><p>${subtitle}</p></div><div class="actions">${actions}</div></div>`;
const panel=(name,body,actions='')=>`<section class="panel"><div class="panel-head"><h2>${name}</h2>${actions}</div>${body}</section>`;
const simpleTable=(cols,rows)=>rows.length?`<div class="table-wrap"><table><thead><tr>${cols.map(c=>`<th>${c[0]}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${cols.map(c=>`<td>${c[1](r)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:empty();
function table(cols,rows,statusesList=[]){const filtered=rows.filter(r=>(!search||JSON.stringify(r).toLowerCase().includes(search.toLowerCase()))&&(!filterStatus||r.status===filterStatus||r.payment_status===filterStatus));const max=Math.max(1,Math.ceil(filtered.length/12));page=Math.min(page,max);return `<div class="toolbar"><input id="table-search" placeholder="${L('搜索记录…','Buscar registros…','Search records…')}" value="${E(search)}">${statusesList.length?`<select id="status-filter"><option value="">${L('全部状态','Todos os status','All statuses')}</option>${statusesList.map(s=>`<option value="${s}" ${filterStatus===s?'selected':''}>${E(st(s))}</option>`).join('')}</select>`:''}<span class="muted">${filtered.length} ${L('条记录','registros','records')}</span></div>${simpleTable(cols,filtered.slice((page-1)*12,page*12))}<div class="pager"><span>${page} / ${max}</span><div class="actions">${button('prev','←','','small')}${button('next','→',max,'small')}</div></div>`}
function metric(name,value,sub=''){return `<div class="metric"><span class="dot"></span><div class="muted">${name}</div><div class="value numeric">${value}</div><div class="mini">${sub||'BRL · R$'}</div></div>`}
function shell(body){const keys=navigationKeys();const icons={wallet:'＋',policies:'✧',dashboard:'◫',orders:'▤',products:'◇',dealers:'♧',inventory:'▦',consignment:'◇',finance:'◉',collections:'↗',commissions:'%',data:'⇅',users:'⚙',audit:'≡'};return `<div class="shell"><aside class="sidebar"><div class="brand">HYNAK</div><div class="brand-note">MOBILITY · BUSINESS</div><nav class="nav">${keys.map((k,i)=>button('nav',`<span class="icon">${icons[k]}</span>${E(title(k))}`,k,view===k?'active':'')).join('')}</nav><div class="sidebar-footer">${L('巴西业务工作台','Workspace Brasil','Brazil business workspace')}<span class="role">${E(D.user.name)} · ${E(D.user.role)}</span></div></aside><main class="main"><header class="topbar"><span class="eyebrow sync-heading">${L('销售 · 库存 · 回款','Vendas · Estoque · Recebimentos','Sales · Inventory · Receipts')}<small id="shared-sync-status" class="shared-sync-status ${sharedSyncError?'sync-failed':''}" role="status" aria-live="polite">${E(syncStatusText())}</small></span><div class="top-actions"><select id="language" aria-label="Language"><option value="zh" ${lang==='zh'?'selected':''}>简体中文</option><option value="pt" ${lang==='pt'?'selected':''}>Português</option><option value="en" ${lang==='en'?'selected':''}>English</option></select><button type="button" class="small shared-sync-button" data-act="syncdata" aria-label="${L('同步数据','Atualizar dados','Sync data')}" title="${L('同步最新数据','Atualizar dados','Sync latest data')}">↻</button><span class="avatar">${E(D.user.name.slice(0,1))}</span>${button('logout',L('退出','Sair','Sign out'),'','small')}</div></header><div class="content">${testNotice()}${body}</div></main></div>`}
const orderCols=()=>[[L('订单 / 经销商','Pedido / Cliente','Order / Dealer'),r=>`<strong>${E(r.number)}</strong><div class="sub">${E(r.dealer)}</div>`],[is('dealer')?L('采购日期 / 类型','Data / Tipo de compra','Purchase date / type'):L('销售日期 / 类型','Data / Tipo','Sale date / type'),r=>`${E(r.sale_date||'—')}<div class="sub">${E(saleTypeName(r.sale_type))}</div>`],[L('金额','Valor','Total'),r=>money(r.total)+(r.consignment_full_settlement?'<div class="sub">'+L('已付款','Pagamentos','Payments')+' '+r.payment_count+L('次',' vezes',' times')+' · '+L('已抵扣','Alocado','Applied')+' '+money(r.received)+'</div>':'')],[L('订单状态','Status do pedido','Order status'),r=>badge(r.status)],[L('付款状态','Pagamento','Payment'),r=>badge(r.payment_status)],[L('到期日','Vencimento','Due'),r=>E(r.due)],[L('尚欠','Pendente','Outstanding'),r=>`<strong class="${r.overdue_days?'money-red':''}">${money(r.outstanding)}</strong>`],['',r=>button('detail',L('详情','Detalhes','Details'),r.id,'small')]];
let dashboardFilters=null,dashboardResult=null,dashboardError='',dashboardBusy=false,dashboardRequest=0;
let dashboardCards=new Set(['outstanding','verified','overdue','order_count','order_amount']),dashboardPreferencesUser=null;
function loadDashboardPreferences(){if(dashboardPreferencesUser===D.user.id)return;dashboardPreferencesUser=D.user.id;try{const saved=JSON.parse(localStorage.getItem('hynak_dashboard_cards_'+D.user.id));if(Array.isArray(saved))dashboardCards=new Set(saved.filter(key=>['outstanding','verified','overdue','order_count','order_amount','receivable','waiting'].includes(key)))}catch{}}

const dashboardDefaults=()=>({start:day().slice(0,7)+'-01',end:day(),basis:'confirmed',dealer_id:'',sales_id:'',sale_type:'',status:'',payment_status:''});
const dashboardBasis=()=>[['confirmed',L('订单生效日期','Confirmação do pedido','Confirmation date')],['sale_date',L('采购 / 销售日期','Data da compra / venda','Purchase / sale date')],['created',L('订单创建日期','Criação do pedido','Creation date')],['due',L('付款到期日','Vencimento','Payment due date')]];
function dashboardSelect(name,label,options,value){return `<div class="field"><label for="df-${name}">${label}</label><select id="df-${name}" name="${name}"><option value="">${L('全部','Todos','All')}</option>${options.map(([k,v])=>`<option value="${E(k)}" ${String(k)===String(value)?'selected':''}>${E(v)}</option>`).join('')}</select></div>`}
function dashboardCardDefinitions(){const m=dashboardResult?.metrics||{};return [
['outstanding',is('dealer')?L('待核销应付款','Pagamentos a conciliar','Payables pending reconciliation'):L('尚未收回','Saldo pendente','Outstanding'),money(m.outstanding),L('所选订单当前应收 − 已抵扣付款','Saldo atual dos pedidos selecionados','Current balance of selected orders')],
['verified',L('期间银行核实实收','Recebimentos do período','Verified receipts in period'),money(m.verified),dashboardResult?.receipt_scope==='order_attributed'?L('按到账日，仅计所选类型 / 状态归属款','Por data bancária, atribuídos ao tipo / status','By bank date, attributed to selected type / status'):L('按银行实际到账日期统计','Por data real do recebimento','By actual bank receipt date')],
['overdue',L('已逾期金额','Valor vencido','Overdue'),money(m.overdue),L('所选订单目前已逾期的未付余额','Saldo vencido atual dos pedidos selecionados','Currently overdue balance of selected orders')],
['order_count',L('期间生效订单数','Pedidos confirmados no período','Confirmed order count'),String(m.order_count??0)+' '+L('笔','pedidos','orders'),L('仅统计已生效销售订单','Somente pedidos de venda confirmados','Confirmed sales orders only')],
['order_amount',L('期间生效订单金额','Valor confirmado no período','Confirmed order amount'),money(m.order_amount),L('所选范围内已生效销售订单合计','Total confirmado nos filtros selecionados','Confirmed sales total for the selected filters')],
['receivable',L('所选订单应收总额','Total a receber selecionado','Selected receivables'),money(m.receivable),L('含应收调整','Inclui ajustes de recebíveis','Includes receivable adjustments')],
['waiting',L('待处理订单数','Pedidos pendentes','Pending order count'),String(m.waiting??0)+' '+L('笔','pedidos','orders'),L('草稿、待审核及待客户确认','Rascunhos e pedidos aguardando análise ou confirmação','Drafts and orders awaiting review or confirmation')]
]}
function dashboardMetricPicker(){if(is('warehouse'))return '';return `<details class="dashboard-card-picker"><summary>${L('自定义显示指标','Personalizar indicadores','Customize visible metrics')}</summary><div class="dashboard-card-options">${dashboardCardDefinitions().map(([key,name])=>`<label><input type="checkbox" name="metric" value="${key}" ${dashboardCards.has(key)?'checked':''}>${name}</label>`).join('')}</div></details>`;}
function dashboardFilterPanel(){
const f=dashboardFilters||(dashboardFilters=dashboardDefaults());
return panel(L('查看范围与指标','Período e indicadores','Date range and metrics'),`<div class="panel-body dashboard-filters"><form id="dashboard-filters-form"><div class="dashboard-presets">${[['month',L('本月','Este mês','This month')],['last_month',L('上月','Mês anterior','Last month')],['today',L('今天','Hoje','Today')],['all',L('全部时间','Todo o período','All time')]].map(([k,v])=>button('dashboard-preset',v,k,'small')).join('')}<span class="sub">${L('或填写自定义起止日期','Ou informe datas personalizadas','Or enter a custom date range')}</span></div><div class="dashboard-filter-grid"><div class="field"><label for="df-start">${L('开始日期','Data inicial','Start date')}</label><input type="date" id="df-start" name="start" value="${E(f.start)}"></div><div class="field"><label for="df-end">${L('结束日期','Data final','End date')}</label><input type="date" id="df-end" name="end" value="${E(f.end)}"></div><div class="field"><label for="df-basis">${L('订单日期口径','Data para os pedidos','Order date basis')}</label><select id="df-basis" name="basis">${dashboardBasis().map(([k,v])=>`<option value="${k}" ${f.basis===k?'selected':''}>${v}</option>`).join('')}</select></div>${!is('dealer')?dashboardSelect('dealer_id',L('经销商','Revendedor','Dealer'),D.dealers.map(d=>[d.id,d.name]),f.dealer_id):''}${is('admin','finance','warehouse')?dashboardSelect('sales_id',L('责任销售','Vendedor','Sales owner'),D.users.filter(u=>u.role==='sales').map(u=>[u.id,u.name]),f.sales_id):''}${dashboardSelect('sale_type',L('销售类型','Tipo de venda','Sale type'),['CASH','CONSIGNMENT','OTHER','WHOLESALE'].map(t=>[t,saleTypeName(t)]),f.sale_type)}${dashboardSelect('status',L('订单状态','Status do pedido','Order status'),['DRAFT','WAITING_INTERNAL_REVIEW','WAITING_FINANCE_REVIEW','WAITING_DEALER_CONFIRMATION','CONFIRMED','PARTIALLY_SHIPPED','SHIPPED','CLOSED','CANCELED','REJECTED','EXPIRED'].map(s=>[s,st(s)]),f.status)}${dashboardSelect('payment_status',L('付款状态','Status do pagamento','Payment status'),['UNPAID','PARTIAL','PAID','OVERDUE','VERIFYING'].map(s=>[s,st(s)]),f.payment_status)}</div>${dashboardMetricPicker()}<div class="actions"><button class="primary" type="submit" ${dashboardBusy?'disabled':''}>${dashboardBusy?L('查询中…','Consultando…','Loading…'):L('应用筛选','Aplicar filtros','Apply filters')}</button>${button('dashboard-reset',L('重置为本月','Redefinir para este mês','Reset to this month'))}</div><p class="sub dashboard-filter-help">${is('warehouse')?L('按已应用日期和订单状态查看待出库与待提货情况；库存始终展示当前值。','Consulte expedições e retiradas por data e status; estoque mostra valores atuais.','Use applied dates and statuses for dispatch and pickup tasks; stock shows current quantities.'):L('未收回和逾期为当前余额；实收按到账日期。待审核订单请按创建日期查看。','Saldos atuais; recebimentos por data bancária. Para pendentes, use a data de criação.','Balances are current; receipts use bank dates. Use creation date for pending orders.')}</p><p class="sub" id="dashboard-draft-status" role="status"></p><p class="form-error" role="alert">${E(dashboardError)}</p></form></div>`);
}
async function refreshDashboard(renderAfter=true){
if(!dashboardFilters)dashboardFilters=dashboardDefaults();
const request=++dashboardRequest;dashboardBusy=true;dashboardError='';dashboardResult=null;
if(renderAfter&&view==='dashboard')render();
try{const [statistics]=await Promise.allSettled([api('/api/dashboard-summary?'+new URLSearchParams(dashboardFilters)),refreshRoleInsights(false)]);if(statistics.status==='rejected')throw statistics.reason;const result=statistics.value;if(request===dashboardRequest){dashboardResult=result;for(const o of Object.values(dashboardRankingOptions))o.visibleSeries=null}}
catch(e){if(request===dashboardRequest)dashboardError=e.message}
finally{if(request===dashboardRequest){dashboardBusy=false;if(renderAfter&&view==='dashboard')render()}}
}
function dashboardDraftNotice(){const el=$('#dashboard-draft-status');if(el)el.textContent=L('筛选条件已更改，请点击“应用筛选”更新统计。','Filtros alterados. Clique em Aplicar filtros.','Filters changed. Select Apply filters to update the results.')}
async function queryDashboard(form){
const v=Object.fromEntries(new FormData(form));delete v.metric;
if(Boolean(v.start)!==Boolean(v.end)||v.start>v.end){dashboardError=L('请填写完整日期范围，开始日期不能晚于结束日期','Informe as duas datas em ordem válida','Enter both dates, with start not after end');form.querySelector('[role=alert]').textContent=dashboardError;return}
dashboardFilters={...dashboardDefaults(),...v};search='';page=1;await refreshDashboard();
}
const dashboardRankingOptions={models:{sort:'quantity',limit:10,view:'bar',interval:'auto',visibleSeries:null},dealers:{sort:'amount',limit:10,view:'bar',interval:'auto',visibleSeries:null}};
let rankingPreferencesUser=null;
function loadDashboardRankingPreferences(){
if(rankingPreferencesUser===D.user.id)return;rankingPreferencesUser=D.user.id;
try{const saved=JSON.parse(localStorage.getItem('hynak_ranking_views_'+D.user.id));for(const kind of ['models','dealers']){const v=saved?.[kind],o=dashboardRankingOptions[kind];if(!v)continue;if(['bar','trend','table'].includes(v.view))o.view=v.view;if(['quantity','amount','order_count'].includes(v.sort))o.sort=v.sort;if([0,10,20].includes(v.limit))o.limit=v.limit;if(['auto','day','week','month'].includes(v.interval))o.interval=v.interval}}catch{}
}
function saveDashboardRankingPreferences(){try{localStorage.setItem('hynak_ranking_views_'+D.user.id,JSON.stringify(Object.fromEntries(Object.entries(dashboardRankingOptions).map(([kind,o])=>[kind,{view:o.view,sort:o.sort,limit:o.limit,interval:o.interval}]))))}catch{}}
function dashboardRankingRows(kind){
const models=kind==='models',options=dashboardRankingOptions[kind];
const rows=[...(dashboardResult?.rankings?.[kind]||[])].sort((a,b)=>b[options.sort]-a[options.sort]||b.amount-a.amount||b.quantity-a.quantity||String(models?a.sku:a.code).localeCompare(String(models?b.sku:b.code))||(models?a.product_id-b.product_id:a.dealer_id-b.dealer_id));
return {rows,shown:(options.limit?rows.slice(0,options.limit):rows).map((row,index)=>({...row,rank:index+1}))};
}
function rankingControl(kind,field,label,choices){return `<div><label for="ranking-${field}-${kind}">${label}</label><select id="ranking-${field}-${kind}" class="ranking-option" data-ranking-kind="${kind}" data-ranking-field="${field}">${choices.map(([value,name])=>`<option value="${value}" ${String(dashboardRankingOptions[kind][field])===String(value)?'selected':''}>${name}</option>`).join('')}</select></div>`}
function dashboardRankingPanel(kind){
const models=kind==='models',options=dashboardRankingOptions[kind],{rows,shown}=dashboardRankingRows(kind);
const name=models?L('车型销售排名','Ranking de modelos','Best-selling models'):L('经销商采购排名','Ranking de revendedores','Top purchasing dealers');
const filters=dashboardResult.filters,range=filters.start?E(filters.start)+' ～ '+E(filters.end):L('全部时间','Todo o período','All time'),basis=dashboardBasis().find(([key])=>key===filters.basis)?.[1];
const metrics=[['quantity',models?L('销量（台）','Unidades vendidas','Units sold'):L('采购数量（台）','Unidades compradas','Units purchased')],['amount',models?L('销售商品金额','Valor dos produtos','Product sales amount'):L('采购商品金额','Valor das compras','Product purchase amount')],['order_count',L('订单笔数','Quantidade de pedidos','Order count')]],metricLabel=metrics.find(([key])=>key===options.sort)[1];
const controls=`<div class="ranking-controls">${rankingControl(kind,'view',L('展示方式','Visualização','View'),[['bar',L('柱状图','Barras','Bar chart')],['trend',L('趋势图','Tendência','Trend chart')],['table',L('表格','Tabela','Table')]])}${rankingControl(kind,'sort',L('统计指标 / 排序','Indicador / ordem','Metric / sort'),metrics)}${rankingControl(kind,'limit',L('显示数量','Exibir','Show'),[[10,L('前10名','Top 10','Top 10')],[20,L('前20名','Top 20','Top 20')],[0,L('全部','Todos','All')]])}${options.view==='trend'?rankingControl(kind,'interval',L('汇总周期','Agrupamento','Time interval'),[['auto',L('自动','Automático','Auto')],['day',rankingIntervalName('day')],['week',rankingIntervalName('week')],['month',rankingIntervalName('month')]]):''}</div>`;
const cols=[[L('排名','Posição','Rank'),r=>`<span class="ranking-place ${r.rank<=3?'ranking-leader':''}">${r.rank}</span>`],[models?L('车型','Modelo','Model'):L('经销商','Revendedor','Dealer'),r=>`<strong class="wrap-text">${E(r.name)}</strong><div class="sub">${E(models?r.sku:r.code)}</div>`],[metrics[0][1],r=>`<strong>${r.quantity}</strong>`],[metrics[1][1],r=>money(r.amount)],[L('订单笔数','Pedidos','Orders'),r=>r.order_count]];
let content=shown.length?(options.view==='table'?simpleTable(cols,shown):options.view==='bar'?rankingBarChart(kind,shown,options,metricLabel):rankingTrendChart(kind,shown,options,metricLabel,dashboardResult.ranking_trends)):`<div class="empty"><strong>${L('所选范围暂无销售记录','Sem vendas neste período','No sales in the selected range')}</strong><span>${L('可调整日期或筛选条件后查询。','Altere as datas ou os filtros.','Try another date range or filter.')}</span></div>`;
return panel(name,`<div class="panel-body ranking-intro"><div class="ranking-period">${range} · ${E(basis)}</div><p>${models?L('按已生效订单的车型成交数量及金额统计。','Unidades e valores dos modelos em pedidos confirmados.','Model quantities and amounts from confirmed orders.'):L('按经销商向 HYNAK 采购的已生效订单统计。','Compras confirmadas dos revendedores junto à HYNAK.','Confirmed purchases from HYNAK by dealer.')}</p><p class="sub">${L('联动上方日期与业务筛选；赠品、运费不计入。','Segue os filtros acima; exclui brindes e frete.','Uses the date and business filters above; excludes gifts and freight.')}</p>${controls}</div>${content}<div class="ranking-footer">${L('显示','Exibindo','Showing')} ${shown.length} / ${rows.length} ${models?L('个车型','modelos','models'):L('个经销商','revendedores','dealers')}</div>`);
}

function dashboardSalesRankingsBody(){return dashboardRankingPanel('models')+dashboardRankingPanel('dealers')}
function dashboardSalesRankings(){return `<div id="dashboard-sales-rankings" class="grid2 sales-rankings">${dashboardSalesRankingsBody()}</div>`}

function dashboard(){
const result=dashboardResult,m=result?.metrics,top=(result?.dealers||[]).filter(d=>d.outstanding>0).sort((a,b)=>b.outstanding-a.outstanding).slice(0,5);
const period=result?(result.filters.start?`${E(result.filters.start)} ～ ${E(result.filters.end)}`:L('全部时间','Todo o período','All time')):'';
const basis=dashboardBasis().find(([key])=>key===(result?.filters.basis||dashboardFilters?.basis))?.[1];
const scopeLabels=result?[result.filters.dealer_id?D.dealers.find(d=>d.id===Number(result.filters.dealer_id))?.name:null,result.filters.sales_id?D.users.find(u=>u.id===Number(result.filters.sales_id))?.name:null,result.filters.sale_type?saleTypeName(result.filters.sale_type):null,result.filters.status?st(result.filters.status):null,result.filters.payment_status?st(result.filters.payment_status):null].filter(Boolean):[];
const heading=head('dashboard',L('按时间、经销商、销售和订单状态查看业务。','Analise por período, cliente, vendedor e status.','Review by date range, dealer, sales owner and order status.'),is('admin','sales','dealer')?button('order','＋ '+newOrderTitle(),'','primary'):'');
let body=heading+dashboardFilterPanel();
if(is('warehouse'))return warehouseDashboardBody(body,result);
if(!result)return body+roleWorkbenchPanel()+`<div class="notice" role="status">${dashboardBusy?L('正在汇总所选范围…','Calculando…','Calculating selected range…'):L('请应用筛选查看统计。','Aplique os filtros para consultar.','Apply filters to view statistics.')}</div>`;
body+=`<div class="dashboard-scope" role="status"><strong>${period}</strong><span>${basis}${scopeLabels.length?' · '+scopeLabels.map(E).join(' · '):''} · ${m.matched_order_count} ${L('笔订单匹配','pedidos encontrados','matching orders')}</span><span>${L('当前余额更新于','Saldos atuais atualizados em','Current balances updated')} ${E(paymentLabel(result.checked_at))}</span></div><div class="metrics dashboard-metrics">${dashboardCardDefinitions().filter(([key])=>dashboardCards.has(key)).map(([key,name,value,sub])=>metric(name,value,sub)).join('')}</div>`;
body+=roleWorkbenchPanel();
body+=`<details class="dashboard-definitions"><summary>${L('统计口径说明','Como os indicadores são calculados','How these metrics are calculated')}</summary><p>${L('日期包含起止当天，使用巴西圣保罗时区。订单明细按所选日期口径筛选；未生效订单没有生效日期，可切换创建日期查看。尚未收回、逾期、应收和已分配款项为所选订单的当前余额，不是历史余额快照。生效订单数及金额不含草稿、待审核、待确认、撤销、拒绝、期初应收及寄售发货。','Datas inclusivas no fuso de São Paulo. Pedidos pendentes não têm data de confirmação; use a data de criação. Saldos são os atuais dos pedidos selecionados, não saldos históricos. As vendas confirmadas excluem pendentes, cancelados, saldos iniciais e remessas em consignação.','Dates are inclusive in São Paulo time. Pending orders have no confirmation date; use creation date. Balances are current balances of selected orders, not historical snapshots. Confirmed sales exclude pending, canceled, opening balances and consignment dispatches.')}</p><p>${result.receipt_scope==='order_attributed'?L('已限定销售类型、订单状态或付款状态：期间实收仅计银行到账日位于所选范围、且归属于这些订单条件的款项；未归属订单的充值不计入。订单日期筛选不改变实际到账日期口径。','Com filtros de tipo ou status, contam somente recebimentos atribuídos a esses pedidos, por data bancária. Recargas sem pedido ficam excluídas.','With type or status filters, receipts include only money attributable to matching orders by actual bank date. Unassigned recharge credit is excluded. Order dates do not replace bank dates.'):L('期间实收按实际到账日期及经销商 / 责任销售筛选，含已核实充值，不含待核实水单。即使订单早于所选期间，其本期到账仍计入；因此它与订单应收不必相等。','Recebimentos por data bancária e cliente/vendedor, incluindo recargas verificadas e excluindo comprovantes pendentes. Podem incluir pagamentos de pedidos anteriores.','Receipts use actual bank dates and dealer/sales filters, including verified recharges and excluding pending claims. Payments for earlier orders can be included.')}</p></details>`;
if(is('dealer'))body+=`<div class="notice">${L('当前可用账户余额','Saldo disponível atual','Current available wallet balance')} <strong>${money(D.metrics.available_credit)}</strong> · ${L('账户余额不随订单日期筛选变化','O saldo da conta não é filtrado pela data dos pedidos','Wallet balance is not filtered by order dates')}</div>`;
body+=dashboardSalesRankings();
body+=panel(L('所选范围订单明细','Pedidos selecionados','Selected order details'),table(orderCols(),result.orders));
body+=`<div class="grid2">${panel(L('所选订单欠款排名','Saldos dos pedidos selecionados','Selected order outstanding balances'),`<div class="panel-body">${top.length?top.map(d=>`<div class="bar-row"><div class="bar-label"><span>${E(d.name)}</span><strong>${money(d.outstanding)}</strong></div><progress class="bar" value="${d.outstanding}" max="${top[0].outstanding}"></progress><div class="sub">${E(d.sales)}</div></div>`).join(''):empty()}</div>`)}${panel(L('所选订单销售汇总','Resumo dos pedidos por vendedor','Selected orders by sales owner'),simpleTable([[L('负责人','Vendedor','Sales owner'),r=>E(r.name)],[L('应收','A receber','Receivable'),r=>money(r.receivable)],[L('已分配实收','Alocado','Allocated'),r=>money(r.received)],[L('尚欠','Pendente','Outstanding'),r=>money(r.outstanding)]],result.sales_summary))}</div>`;
if(!is('warehouse'))body+=panel(L('期间已核实实收明细','Recebimentos verificados no período','Verified receipts in the period'),simpleTable([[L('到账日期','Data bancária','Bank receipt date'),r=>E(r.date)],[L('经销商','Revendedor','Dealer'),r=>E(r.dealer)],[L('本次统计金额','Valor incluído','Included amount'),r=>money(r.selected_amount)],[L('入账类型','Tipo','Receipt type'),r=>r.is_recharge?L('充值到账','Recarga','Recharge'):L('订单付款','Pagamento','Order payment')]],result.receipts));
return body+panel(L('当前库存快览（不受订单日期筛选影响）','Estoque atual (independe das datas dos pedidos)','Current stock (not filtered by order dates)'),simpleTable(inventoryCols(),D.inventory.slice(0,8)))+panel(L('当前催收待办（不受订单日期筛选影响）','Cobranças atuais (independem das datas dos pedidos)','Current follow-up tasks (not filtered by order dates)'),simpleTable(followupCols(),D.followups.filter(f=>f.next_date<=day()).slice(0,6)));
}

