const stockInfo=L('可用库存已扣除锁货，不含经销商寄售库存。每30秒自动更新。','Estoque disponível desconta reservas e exclui consignação. Atualização a cada 30 segundos.','Available stock excludes reservations and consignment. Updates every 30 seconds.');
const cols=[['SKU',r=>`<strong>${E(r.sku)}</strong>`],[L('车型 / 商品名称','Modelo / Produto','Model / Product'),r=>E(r.name)],[is('dealer')?L('采购价','Preço de compra','Purchase price'):L('标准批发价','Preço padrão','Standard wholesale'),r=>money(r.price)],[L('可用库存（台）','Estoque disponível','Available units'),r=>`<strong>${r.available_quantity??0}</strong>`],[L('供货状态','Disponibilidade','Availability'),r=>r.in_stock?L('有货','Em estoque','In stock'):L('待补货 · 可预订','Reposição · encomendar','Backorder available')]];
