function f(name,label,type='text',value='',required=true,extra=''){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${E(value)}" ${required?'required':''} ${extra}></div>`}
function sel(name,label,options,value='',required=true){return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}" ${required?'required':''}><option value="">—</option>${options.map(o=>`<option value="${E(o[0])}" ${String(o[0])===String(value)?'selected':''}>${E(o[1])}</option>`).join('')}</select></div>`}
function ta(name,label,value='',required=false){return `<div class="field full"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}" ${required?'required':''}>${E(value)}</textarea></div>`}
function check(name,label,value=false){return `<div class="check"><input type="checkbox" id="f-${name}" name="${name}" ${value?'checked':''}><label for="f-${name}">${label}</label></div>`}
const dealerOpts=()=>D.dealers.map(d=>[d.id,d.name]),salesOpts=()=>D.users.filter(u=>u.role==='sales').map(u=>[u.id,u.name]),prodOpts=()=>D.products.filter(p=>p.active).map(p=>[p.id,`${p.sku} · ${p.name} · ${money(p.price)}`]),wareOpts=()=>D.warehouses.map(w=>[w.id,warehouseLabel(w)]),orderOpts=()=>D.orders.filter(o=>o.outstanding>0).map(o=>[o.id,`${o.number} · ${o.dealer} · ${money(o.outstanding)}`]);
function modal(name,body,submit,submitText){delete $('#modal').dataset.liveOrderId;delete $('#modal').dataset.liveCreditId;formKey=crypto.randomUUID();formSubmit=submit;$('#dialog-content').innerHTML=`<div class="dialog-head"><h2>${name}</h2>${button('close','×')}</div><form id="dialog-form"><div class="dialog-body">${body}<div class="form-error" role="alert"></div></div><div class="dialog-footer">${button('close',L('关闭','Fechar','Close'))}${submit?`<button class="primary" type="submit">${submitText||L('保存','Salvar','Save')}</button>`:''}</div></form>`;$('#modal').showModal()}
function values(){const form=$('#dialog-form'),out=Object.fromEntries(new FormData(form));form.querySelectorAll('input[type=checkbox]').forEach(c=>out[c.name]=c.checked);return out}
