const due=$('#due-fields'), paid=$('#cash-fields'),method=$('#f-payment_method');
if(method){method.disabled=!cash;if(!cash)method.value='BANK'}
if($('#payment-method-fields'))$('#payment-method-fields').hidden=!cash;
const balance=cash&&method?.value==='BALANCE',did=is('dealer')?D.user.dealer_id:Number($('#f-dealer_id')?.value),w=(D.wallets||[]).find(w=>w.dealer_id===did);
