function demoForm(id){
const o=D.orders.find(o=>o.id===Number(id));if(!o)return;
const blocked=new Map();
for(const other of D.orders.filter(x=>x.dealer_id===o.dealer_id&&x.id!==o.id&&!['CANCELED','REJECTED','EXPIRED'].includes(x.status))){
for(const line of other.lines.filter(l=>!l.gift&&(l.demo_applied||other.promotion==='DEMO'))){
if(!blocked.has(line.product_id)||other.confirmed)blocked.set(line.product_id,other);
}}
const giftPolicy=o.promotion==='TEN_PLUS_ONE'||o.lines.some(l=>l.gift);
const rows=o.lines.filter(l=>!l.gift).map(l=>{
const used=blocked.get(l.product_id),selected=l.demo_applied||o.promotion==='DEMO';
const note=used?(used.confirmed?L('已享受过，不能再次勾选','Demo já utilizado; não pode repetir','Already used; cannot select again'):L('已在待处理订单勾选，请先完成或取消该订单','Selecionado em pedido pendente; conclua ou cancele primeiro','Selected on a pending order; complete or cancel it first'))+' · '+E(used.number):giftPolicy?L('不能与买10送1叠加，请先修订方案','Não acumula com 10+1; revise a política primeiro','Cannot combine with buy 10 get 1; revise the policy first'):L('尚未享受，可勾选一次','Disponível uma única vez','Available once');
return `<label class="policy-choice"><input type="checkbox" class="demo-model" value="${l.product_id}" data-quantity="${l.quantity}" data-standard="${l.standard_price}" data-current="${l.unit_price}" data-was-demo="${selected?'1':'0'}" ${selected?'checked':''} ${(used&&!selected)||giftPolicy?'disabled':''}><span><strong>${E(l.sku)} · ${E(l.name)} × ${l.quantity}</strong><span class="sub">${L('正常单价','Preço padrão','Standard unit price')}: ${money(l.standard_price)} → Demo: ${money(Math.round(l.standard_price*.8))}</span><span class="sub">${note}</span></span></label>`;
}).join('');
modal(L('设置 Demo 计划','Definir plano Demo','Set Demo plan'),`<p class="notice">${L('经销商正常下单后，由销售或管理员逐车型勾选八折。每个经销商每种车型只能享受一次，后续再次采购该车型不再享受。无需另走政策申请。','Após o pedido pelo preço normal, vendas ou administrador seleciona Demo por modelo. Uma vez por cliente/modelo; compras seguintes não recebem o desconto. Sem solicitação separada.','After ordering at normal prices, sales or an administrator selects Demo per model. Once per dealer/model; later purchases of that model receive no further Demo discount. No separate policy application.')}</p><p class="sub">${E(o.number)} · ${E(o.dealer)}</p><div id="demo-models" data-freight="${o.freight}">${rows}</div><div id="demo-total" class="notice" aria-live="polite"></div><p class="sub">${L('仅可修改未生效且尚无银行核实到账的订单。现付仍须财务核实；原付款水单保留，多付部分作为预存款。整单撤销后释放名额。','Somente antes da ativação e de recebimentos verificados. À vista exige financeiro; comprovantes são preservados e excedente vira crédito. Cancelar o pedido libera a oportunidade.','Only before activation and any verified bank receipt. Cash still requires finance verification; proof is retained and excess payment becomes credit. Whole-order cancellation releases the opportunity.')}</p>`,()=>action('order.demo',{order_id:o.id,version:o.version,product_ids:[...document.querySelectorAll('.demo-model:checked')].map(el=>Number(el.value))}),L('保存 Demo 设置','Salvar Demo','Save Demo settings'));
previewDemo();
}
function previewDemo(){
if(!$('#demo-total'))return;
let total=Number($('#demo-models').dataset.freight)||0;
for(const el of document.querySelectorAll('.demo-model')){
const standard=Number(el.dataset.standard),price=el.checked?Math.round(standard*.8):el.dataset.wasDemo==='1'?standard:Number(el.dataset.current);
total+=Number(el.dataset.quantity)*price;
}
$('#demo-total').textContent=L('修改后订单金额：','Novo total: ','Updated order total: ')+money(total);
}
