if(act==='dashboard-preset'){const form=$('#dashboard-filters-form'),v=Object.fromEntries(new FormData(form)),today=day();delete v.metric;if(arg==='all'){v.start='';v.end=''}else if(arg==='today'){v.start=today;v.end=today}else if(arg==='last_month'){const first=new Date(today.slice(0,7)+'-01T12:00:00-03:00');first.setUTCDate(first.getUTCDate()-1);v.end=first.toISOString().slice(0,10);v.start=v.end.slice(0,7)+'-01'}else{v.start=today.slice(0,7)+'-01';v.end=today}dashboardFilters=v;search='';page=1;await refreshDashboard();return}

