if(act==='addstockline'){if(document.querySelectorAll('.stock-line').length>=100){toast(L('最多100行SKU','Máximo de 100 linhas','Maximum 100 SKU rows'),true);return}$('#stock-lines').insertAdjacentHTML('beforeend',stockLineEditor());return}
