if(act==='policy'){policyForm(arg);return}
if(act==='product'){const p=D.products.find(p=>p.id===Number(arg));modal(L('商品与标准价','Produto e preço padrão','Product & standard price'),`<div class="form-grid">${f('sku','SKU','text',p?.sku)}${f('name',L('名称','Nome','Name'),'text',p?.name)}${f('price',L('标准批发价 R$','Preço padrão R$','Standard price R$'),'number',amt(p?.price),true,'min="0" step="0.01"')}</div>${check('active',L('在售','Ativo','Active'),p?.active??true)}`,v=>action('product.save',{...v,id:p?.id}));return}
