function allocationRow(){return `<div class="form-grid allocation-row"><div class="field"><label>${L('目标订单','Pedido','Order')}</label><select class="allocate-order" required>${orderOpts().map(o=>`<option value="${o[0]}">${E(o[1])}</option>`).join('')}</select></div><div class="field"><label>${L('分配金额 R$','Alocar R$','Allocate R$')}</label><input class="allocate-amount" type="number" min="0.01" step="0.01" required></div></div>`}
function auth(page){const setup=page==='setup';$('#root').innerHTML=`<div class="auth"><section class="auth-brand"><div class="brand">HYNAK</div><div><div class="eyebrow">BUSINESS WORKSPACE / BRASIL</div><h1>${L('让业务向前，<br>让每一笔有据可查。','Seu negócio em movimento.<br>Cada transação, no controle.','Move your business forward.<br>Account for every transaction.')}</h1><p>${L('订单、库存、寄售与真实回款，在一个工作台协作。','Pedidos, estoque, consignação e recebimentos em um só lugar.','Orders, inventory, consignments and verified payments in one workspace.')}</p></div><small>HYNAK · MOBILITY FOR EVERYDAY</small></section><section class="auth-main"><div class="auth-card"><select id="language" aria-label="Language"><option value="zh" ${lang==='zh'?'selected':''}>简体中文</option><option value="pt" ${lang==='pt'?'selected':''}>Português</option><option value="en" ${lang==='en'?'selected':''}>English</option></select><br><br>${testNotice()}<h2>${setup?L('初始化业务工作台','Configurar workspace','Set up your workspace'):L('欢迎回来','Bem-vindo de volta','Welcome back')}</h2><p class="muted">${setup?L('创建首个管理员。系统不会预填真实业务余额。','Crie o administrador. Nenhum saldo fictício será criado.','Create the administrator. No business balances are prefilled.'):L('登录以继续管理业务','Entre para gerenciar seu negócio','Sign in to manage your business')}</p><form id="auth-form">${f('username',L('登录账号','Usuário','Username'),'text','',true,'autocomplete="username"')}${setup?f('name',L('管理员姓名','Nome do administrador','Administrator name')):''}${f('password',L('密码','Senha','Password'),'password','',true,`minlength="10" autocomplete="${setup?'new-password':'current-password'}"`)}${setup?f('setup_token',L('云端初始化密钥（本地留空）','Token de configuração (local: vazio)','Cloud setup token (blank locally)'),'password','',false):''}<div class="auth-error" role="alert"></div><button class="primary">${setup?L('创建管理员','Criar administrador','Create administrator'):L('登录工作台 →','Entrar →','Sign in →')}</button></form></div></section></div>`}
async function quote(){const token=location.pathname.split('/').pop();let q;try{q=await api('/api/quote/'+token)}catch(e){$('#root').innerHTML=`<div class="quote"><div class="brand">HYNAK</div><div class="panel panel-body"><h1>${L('链接无法使用','Link indisponível','Link unavailable')}</h1><p>${E(e.message)}</p></div></div>`;return}$('#root').innerHTML=`<main class="quote">${testNotice()}<div class="actions"><div class="brand">HYNAK</div><select id="language"><option value="pt" ${lang==='pt'?'selected':''}>Português</option><option value="zh" ${lang==='zh'?'selected':''}>中文</option><option value="en" ${lang==='en'?'selected':''}>English</option></select></div><p class="eyebrow">ORDER CONFIRMATION / ${E(q.number)} / v${q.version}</p><section class="panel"><div class="panel-body"><h1>${L('请核对您的订单','Confira seu pedido','Review your order')}</h1><p class="muted">${L('最终报价已经 HYNAK 审核；请主动点击确认或拒绝。','Cotação aprovada pela HYNAK. Confirme ou recuse abaixo.','HYNAK has approved this final quote. Choose confirm or reject below.')}</p></div>${simpleTable([['SKU',l=>`${E(l.name)}<div class="sub">${l.gift?L('赠品','Brinde','Gift'):L('标准价','Padrão','Standard')+' '+money(l.standard_price)}</div>`],[L('数量','Qtd.','Qty'),l=>l.quantity],[L('成交单价','Preço final','Final price'),l=>money(l.unit_price)]],q.lines)}<div class="panel-body"><div class="totals"><span>${L('订单总额','Total','Order total')}</span><span>${money(q.total)}</span></div><p>${L('优惠','Promoção','Promotion')}: ${E(promotionName(q.promotion))} · ${L('运费','Frete','Freight')}: ${money(q.freight)}</p><p>${L('销售日期','Data da venda','Sale date')}: ${E(q.sale_date||'—')} · ${E(saleTypeName(q.sale_type))}</p>${q.sale_type==='CASH'?`<p>${L('付款时间','Pagamento','Payment time')}: <strong>${E(paymentLabel(q.payment_at))}</strong></p>`:`<p>${L('经销商付款到期日','Vencimento do revendedor','Dealer payment due date')}: <strong>${E(q.due)}</strong></p>`}<p class="wrap-text">${E(q.terms)}</p><p class="sub">${L('报价有效至','Válido até','Valid until')}: ${E(q.expires.slice(0,10))}</p><br>${q.action?`<div class="notice">${q.action==='CONFIRM'?L('您已确认订单，订单已生效。','Pedido confirmado e ativo.','Order confirmed and active.'):L('您已拒绝此订单。','Pedido recusado.','Order declined.')}</div>`:`<div class="quote-actions">${button('quote-confirm',L('确认订单','Confirmar pedido','Confirm order'),'','primary')}${button('quote-reject',L('拒绝','Recusar','Decline'),'','danger')}</div>`}<p class="form-error" role="alert"></p></div></section><p class="sub">${L('确认操作将记录订单版本、时间及动作。此功能不代表法律电子签章。','Registramos versão, data e ação. Não constitui assinatura eletrônica legal.','We record the order version, time and action. This is not a legal electronic signature.')}</p></main>`}
document.addEventListener('click',async event=>{const b=event.target.closest('[data-act]');if(!b)return;const act=b.dataset.act;try{if(act==='removeconsignmentpayment'){b.closest('.consignment-payment-row').remove();syncConsignmentPayments();return}if(act==='removestockline'){if(document.querySelectorAll('.stock-line').length===1){toast(L('至少保留一行SKU','Mantenha pelo menos um SKU','Keep at least one SKU row'),true);return}b.closest('.stock-line').remove();return}if(act==='removeline'){if(document.querySelectorAll('.line-editor').length===1){toast(L('至少保留一行SKU','Mantenha pelo menos um SKU','Keep at least one SKU row'),true);return}b.closest('.line-editor').remove();previewOrderPolicy();return}if(act.startsWith('quote-')){b.disabled=true;await api('/api/quote/'+location.pathname.split('/').pop(),{action:act==='quote-confirm'?'CONFIRM':'REJECT'});await quote();return}b.disabled=true;await dispatch(act,b.dataset.args)}catch(e){toast(e.message,true)}finally{if(b.isConnected)b.disabled=false}});
document.addEventListener('submit',async event=>{event.preventDefault();const form=event.target;if(form.id==='dialog-form'&&!formSubmit)return;const b=form.querySelector('button[type=submit],button.primary');if(b)b.disabled=true;try{if(form.id==='auth-form'){const body=Object.fromEntries(new FormData(form));await api(document.body.dataset.page==='setup'?'/api/setup':'/api/login',body);location.reload()}else if(form.id==='dashboard-filters-form'){await queryDashboard(form)}else if(form.id==='dialog-form'&&formSubmit){const cb=formSubmit,result=await cb(values());if(!result?.keep){$('#modal').close();toast(L('已保存','Salvo','Saved'));await load()}}}catch(e){const target=form.querySelector('.form-error,.auth-error');if(target)target.textContent=e.message;else toast(e.message,true)}finally{if(b?.isConnected)b.disabled=false}});
document.addEventListener('change',async event=>{
if(['iv-kind','iv-warehouse','cs-dealer','cs-location'].includes(event.target.id)){
if(event.target.id==='iv-kind'){inventorySelection.kind=event.target.value;inventorySelection.warehouse_id=''}
if(event.target.id==='iv-warehouse')inventorySelection.warehouse_id=event.target.value;
if(event.target.id==='cs-dealer'){consignmentSelection.dealer_id=event.target.value;consignmentSelection.warehouse_id=''}
if(event.target.id==='cs-location')consignmentSelection.warehouse_id=event.target.value;
search='';filterStatus='';page=1;render();try{await load()}catch(e){toast(e.message,true)}return;
}
if(event.target.closest('.consignment-payment-row')){syncConsignmentPayments();return}if(event.target.id==='f-claim_id'&&$('#receipt-claim-preview')){receiptClaimPreview();$('#f-amount').value='';$('#f-reference').value='';return}if(event.target.classList.contains('ranking-option')){const options=dashboardRankingOptions[event.target.dataset.rankingKind],field=event.target.dataset.rankingField;options[field]=field==='limit'?Number(event.target.value):event.target.value;if(['sort','limit'].includes(field))options.visibleSeries=null;saveDashboardRankingPreferences();$('#dashboard-sales-rankings').innerHTML=dashboardSalesRankingsBody();return}if(event.target.closest('.dashboard-card-options')){if(event.target.checked)dashboardCards.add(event.target.value);else dashboardCards.delete(event.target.value);try{localStorage.setItem('hynak_dashboard_cards_'+D.user.id,JSON.stringify([...dashboardCards]))}catch{}const grid=$('.dashboard-metrics');if(grid)grid.innerHTML=dashboardCardDefinitions().filter(([key])=>dashboardCards.has(key)).map(([key,name,value,sub])=>metric(name,value,sub)).join('');return}if(event.target.closest('#dashboard-filters-form')){dashboardDraftNotice();return}if(event.target.classList.contains('demo-model')){previewDemo();return}if($('#warehouse-info-fields')&&event.target.id==='f-kind'){syncWarehouseDealer();return}if($('#stock-movement-fields')&&['f-kind','f-warehouse_id'].includes(event.target.id)){syncStockFields();return}if(event.target.id==='f-address_state'){dealerCityOptions(true);return}if(event.target.id==='f-address_city_id'){syncDealerAddress();return}if(event.target.id==='f-wallet_dealer'){walletDealerId=event.target.value;render();return}if(['f-sale_type','f-payment_method'].includes(event.target.id)){syncSaleFields();return}if(event.target.id==='f-dealer_id'){syncSaleFields();return}if(event.target.name==='policy_id'||event.target.closest('.line-editor')){previewOrderPolicy();return}if(event.target.name?.startsWith('cf_')){collectionFilter[event.target.name.slice(3)]=event.target.value;page=1;render();return}if(event.target.id==='language'){lang=event.target.value;localStorage.setItem('hynak_language',lang);if(D)render();else if(document.body.dataset.page==='confirm')await quote();else auth(document.body.dataset.page)}if(event.target.id==='status-filter'){filterStatus=event.target.value;page=1;render()}});
document.addEventListener('input',event=>{if(event.target.closest('.consignment-payment-row')){syncConsignmentPayments();return}if(event.target.closest('#dashboard-filters-form')){dashboardDraftNotice();return}if(event.target.id==='f-freight'||event.target.closest('.line-editor')){previewOrderPolicy();return}if(event.target.id==='city-search'){dealerCityOptions();return}if(event.target.name?.startsWith('address_')){syncDealerAddress();return}if(event.target.id==='table-search'){const position=event.target.selectionStart;search=event.target.value;page=1;render();$('#table-search')?.focus();$('#table-search')?.setSelectionRange(position,position)}});
(async()=>{try{const p=document.body.dataset.page;if(p==='app')await load();else if(p==='confirm'){if(!localStorage.getItem('hynak_language'))lang='pt';await quote()}else auth(p)}catch(e){$('#root').textContent=e.message}})();

document.addEventListener('focusout',event=>{if(event.target.id==='f-cnpj')event.target.value=formatCnpj(event.target.value);if(event.target.id==='f-address_cep'){event.target.value=formatCep(event.target.value);syncDealerAddress()}});
